/**
 * [MAIN] Composition root + frame loop. Owned by the main session — builders do not edit this file.
 *
 * Frame update order (one simulation step):
 *   input → player → zones (proximity transfers) → level (stations, NPCs, machines, progression)
 *   → registered updatables → flights (arcs land) → tweens → particles → environment → juice
 *   → camera → shadow focus → HUD (projects world anchors) → render
 */
import * as THREE from 'three';
import { BUSINESSES, CREW, DAYNIGHT, DEMAND, ECONOMY, LAYOUT, PADS, PLAYER, PRESTIGE, QUARTERS, RIDGE, SAVE, TIMING, TOWN, UPGRADES, VILLAGE, type BusinessId } from '../config';
import { EventBus } from '../core/EventBus';
import { Economy } from '../core/Economy';
import {
  SalesMeter,
  clearSave,
  freshRequested,
  loadSave,
  mergeState,
  sanitizeState,
  newSeasonSave,
  offlineEarnings,
  writeSave,
  type SaveData,
} from '../core/Save';
import { TweenManager } from '../core/Tween';
import { Upgrades } from '../core/Upgrades';
import { DayNight } from '../core/DayNight';
import { RushHours } from '../core/Rush';
import { Quests } from '../core/quests';
import {
  createGameState,
  type GameContext,
  type GameEvents,
  type PadId,
  type Updatable,
  type UpgradeId,
} from '../core/types';
import { Renderer } from '../render/Renderer';
import { CameraRig } from '../render/CameraRig';
import { Input } from '../input/Input';
import { ColliderWorld } from '../world/Colliders';
import { Environment } from '../world/Environment';
import { Player } from '../entities/Player';
import { ItemPool } from '../items/ItemPool';
import { FlightSystem } from '../items/FlightSystem';
import { ZoneSystem } from '../items/Zones';
import { Particles } from '../fx/Particles';
import { AudioFX } from '../fx/Audio';
import { JuiceDirector } from '../fx/JuiceDirector';
import { Fireworks } from '../fx/Fireworks';
import { HUD } from '../ui/HUD';
import { readFpsCap, writeFpsCap, type FpsCap } from '../core/fps';
import { Level } from '../level/Level';

type Writable<T> = { -readonly [K in keyof T]: T[K] };

/** Longest step the real-time loop will take (tab switches, hitches). */
const MAX_DT = 1 / 20;

export interface DebugApi {
  game: Game;
  ctx: GameContext;
  /** Gameplay composition root (stations, NPC queues, pads, progression). */
  level: Level;
  /** Read-only tuning tables (bots/tests derive positions from these instead of hard-coding). */
  config: {
    LAYOUT: typeof LAYOUT;
    PADS: typeof PADS;
    ECONOMY: typeof ECONOMY;
    PLAYER: typeof PLAYER;
    TIMING: typeof TIMING;
    UPGRADES: typeof UPGRADES;
    CREW: typeof CREW;
    VILLAGE: typeof VILLAGE;
    DEMAND: typeof DEMAND;
    QUARTERS: typeof QUARTERS;
    RIDGE: typeof RIDGE;
    PRESTIGE: typeof PRESTIGE;
    BUSINESSES: typeof BUSINESSES;
    TOWN: typeof TOWN;
  };
  state(): Record<string, unknown>;
  pause(): void;
  resume(): void;
  /** Advance the simulation by `seconds` in fixed steps without rendering, then render once. */
  simulate(seconds: number, dt?: number): Record<string, unknown>;
  render(): void;
  /** Screen-space move override (x right, y up); pass null to release. */
  setMove(x: number | null, y?: number): void;
  /** Autopilot the player toward a world XZ point (cleared on arrival). */
  moveTo(x: number, z: number): void;
  teleport(x: number, z: number): void;
  addMoney(n: number): void;
  skipIntro(): void;
  unlock(id: PadId): void;
  /** Shop purchase as if from the panel (spends money). False if not possible. */
  buy(id: UpgradeId): boolean;
  /** Jump an upgrade to a level for free (tests). */
  setUpgrade(id: UpgradeId, level: number): void;
  /** Open the village gate now. */
  revealVillage(): void;
  /** Set plot `plot` (−1 = Great Lodge) to `tier` at once (tests). */
  buildPlot(plot: number, tier: number): void;
  /** Set the crew bunkhouse to `tier` (−1 = none) at once (tests). */
  buildQuarters(tier: number): void;
  /** Wave 9: open the Market Town now / choose + finish lot `lot` as building `id` (plays the build moment). */
  revealTown(): void;
  buildTown(lot: number, id: BusinessId): void;
  /** Start the next season (prestige) now: writes the new-season save and reloads. */
  newSeason(): void;
  /** Start a rush hour now (tests). */
  startRush(seconds?: number): void;
  /** Jump the day/night clock to cycle share `p` (0..1; 0.75 = deep night). */
  setTimeOfDay(p: number): void;
  /** Write the save now; returns what was written (null when saving is off: `?fresh`, reset, no storage). */
  save(): SaveData | null;
  /** The save that would be written now (not written). */
  saveData(): SaveData;
  /** Delete the save (the running game keeps going; the next autosave writes a new one). */
  clearSave(): void;
  /** Offline earnings this game would get after `seconds` away (for tests). */
  offlinePreview(seconds: number): { amount: number; seconds: number };
}

declare global {
  interface Window {
    __WINTERLAND__?: DebugApi;
  }
}

export class Game {
  readonly ctx: GameContext;
  private readonly updatables: Updatable[] = [];
  private pendingRemovals = new Set<Updatable>();
  private readonly juice: JuiceDirector;
  private readonly level: Level;
  private running = false;
  private paused = false;
  private lastTime = 0;
  /** Frame cap; frames arriving early are skipped (sim and render) so the sim never slows (MAX_DT is 50 ms). */
  fpsCap: FpsCap = readFpsCap();
  private lastFrame = 0;
  /** Saving is off for `?fresh` pages and after a reset (until the reload). */
  private saving: boolean;
  private saveTimer: number = SAVE.interval;
  private readonly sales: SalesMeter;

  constructor(container: HTMLElement, hudRoot: HTMLElement) {
    const renderer = new Renderer(container);
    const events = new EventBus<GameEvents>();
    const tweens = new TweenManager();
    // Load BEFORE anything is built: every system initialises itself from state (see docs/DESIGN.md).
    const fresh = freshRequested();
    this.saving = !fresh;
    const save = fresh ? null : loadSave();
    const state = createGameState();
    if (save) {
      mergeState(state, save.state);
      sanitizeState(state);
    }
    const economy = new Economy(events, state, save ? save.money : ECONOMY.startMoney);
    const upgrades = new Upgrades(state, economy, events);
    const colliders = new ColliderWorld();
    const input = new Input(renderer.domElement);
    const cameraRig = new CameraRig(renderer.camera);

    // Built progressively in dependency order (see GameContext docs), then frozen as read-only.
    const ctx = {
      scene: renderer.scene,
      camera: renderer.camera,
      renderer,
      events,
      tweens,
      state,
      economy,
      upgrades,
      colliders,
      input,
      cameraRig,
      dayNight: new DayNight(state, events),
      rush: new RushHours(state, events),
      quests: new Quests(state, economy, events),
      time: { elapsed: 0, frame: 0 },
      addUpdatable: (u: Updatable) => {
        this.pendingRemovals.delete(u);
        if (!this.updatables.includes(u)) this.updatables.push(u);
      },
      removeUpdatable: (u: Updatable) => {
        this.pendingRemovals.add(u);
      },
    } as Writable<GameContext>;
    this.ctx = ctx;

    ctx.particles = new Particles(ctx);
    ctx.audio = new AudioFX();
    ctx.hud = new HUD(ctx, hudRoot);
    ctx.items = new ItemPool(ctx);
    ctx.flights = new FlightSystem(ctx);
    ctx.zones = new ZoneSystem(ctx);
    ctx.environment = new Environment(ctx);
    ctx.player = new Player(ctx);
    this.juice = new JuiceDirector(ctx);
    new Fireworks(ctx); // wave 9: era-up fireworks (self-registers as an updatable)
    this.level = new Level(ctx);
    if (save) this.level.restoreWorld(save.world);
    this.sales = new SalesMeter(ctx, save?.salesRate ?? 0);

    input.onFirstGesture(() => ctx.audio.unlock());
    cameraRig.follow(ctx.player.object);
    cameraRig.resize(renderer.width, renderer.height);
    cameraRig.snapToTarget();
    ctx.hud.setMoney(economy.money, false);

    window.addEventListener('resize', () => this.resize());
    window.visualViewport?.addEventListener('resize', () => this.resize());
    window.addEventListener('pagehide', () => this.save());
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'hidden') this.save();
    });
    events.on('game:reset', () => this.reset());
    // wave 10: keyboard shortcuts and zoom become events; the HUD and the camera listen
    input.onShortcut((s) => {
      if (s === 'escape') events.emit('ui:escape', {});
      else if (s === 'mute') events.emit('ui:mute', {});
      else if (s === 'fullscreen') events.emit('ui:fullscreen', {});
      else events.emit('camera:zoom', { delta: s === 'zoomIn' ? 0.1 : -0.1 });
    });
    input.onZoom((delta) => events.emit('camera:zoom', { delta }));
    events.on('settings:fps', ({ cap }) => this.setFpsCap(cap));
    events.on('save:restore', ({ text }) => this.restore(text));
    events.on('camera:zoom', ({ delta }) => cameraRig.setUserZoom(cameraRig.userZoom + delta));
    events.on('season:new', () => this.newSeason());
    this.installDebugApi();
    this.level.start();

    if (save) {
      const away = offlineEarnings(save, Date.now());
      if (away.amount > 0) {
        // Credit NOW and write it down at once: an autosave / pagehide before the player taps the card would
        // otherwise rewrite savedAt and the earnings would vanish. The card is only informational; the new
        // savedAt also makes a second credit from the same absence impossible.
        ctx.economy.add(away.amount);
        this.save();
        ctx.hud.showOfflineEarnings(away.amount, away.seconds, () => {
          ctx.events.emit('offline:collected', { amount: away.amount }); // coin burst only
        });
      }
    }
  }

  /** The save as it would be written now. */
  saveData(): SaveData {
    const c = this.ctx;
    return {
      v: SAVE.version,
      savedAt: Date.now(),
      // Cash bundles still flying back to the wallet are not banked yet (CashStack.inFlightValue).
      money: c.economy.money + c.player.back.inFlightValue,
      state: c.state,
      world: this.level.snapshotWorld(),
      salesRate: this.sales.rate,
    };
  }

  /** Write the save (no-op when saving is off). */
  save(): SaveData | null {
    if (!this.saving) return null;
    const data = this.saveData();
    return writeSave(data) ? data : null;
  }

  /** Settings → Reset: wipe the save and start over. */
  private reset(): void {
    this.saving = false;
    clearSave();
    location.reload();
  }

  /** Settings → Restore save: stop autosaving (the pagehide save would overwrite it), write the text, reload. */
  private restore(text: string): void {
    this.saving = false;
    try {
      localStorage.setItem(SAVE.key, text);
    } catch {
      this.ctx.hud.toast("Couldn't store the save.", { small: true });
      return;
    }
    location.reload();
  }

  /** After the finale: start the next season (prestige) from a fresh save and reload. */
  private newSeason(): void {
    this.saving = false;
    if (!writeSave(newSeasonSave(this.ctx.state, Date.now()))) {
      // Storage is full / blocked: reloading would restart the old season without the bonus. Stay put.
      this.saving = true;
      this.ctx.hud.toast("Couldn't save the new season", { sub: 'Check your browser storage and try again', duration: 4 });
      return;
    }
    location.reload();
  }

  /** Start the real-time loop. */
  start(): void {
    if (this.running) return;
    this.running = true;
    this.lastTime = performance.now();
    const loop = (now: number) => {
      if (!this.running) return;
      requestAnimationFrame(loop);
      if (this.fpsCap) {
        // allow a little slack so a 60 Hz display under a 60 cap doesn't drop to 30 from jitter
        if (now - this.lastFrame < 1000 / this.fpsCap - 2) return;
        this.lastFrame = now;
      }
      const dt = Math.min((now - this.lastTime) / 1000, MAX_DT);
      this.lastTime = now;
      if (!this.paused && dt > 0) this.step(dt);
      this.ctx.renderer.render();
    };
    requestAnimationFrame(loop);
  }

  /** Settings → Display: 0 (uncapped), 30 or 60. Persisted. */
  setFpsCap(cap: FpsCap): void {
    this.fpsCap = cap;
    writeFpsCap(cap);
  }

  /** One simulation step. */
  step(dt: number): void {
    const c = this.ctx;
    c.time.elapsed += dt;
    c.time.frame++;
    c.state.playTime += dt;

    c.input.update();
    c.player.update(dt);
    c.zones.update(dt);
    this.level.update(dt);
    c.dayNight.update(dt);
    c.rush.update(dt);
    c.quests.update(dt);
    this.flushRemovals();
    for (let i = 0; i < this.updatables.length; i++) {
      const u = this.updatables[i]!;
      if (!this.pendingRemovals.has(u)) u.update(dt);
    }
    this.flushRemovals();
    c.flights.update(dt);
    c.tweens.update(dt);
    c.particles.update(dt);
    c.environment.update(dt);
    this.juice.update(dt);
    c.cameraRig.update(dt);
    c.renderer.setShadowFocus(c.cameraRig.target);
    c.hud.update(dt);

    this.saveTimer -= dt;
    if (this.saveTimer <= 0) {
      this.saveTimer = SAVE.interval;
      this.save();
    }
  }

  /** Fast-forward the simulation (tests). */
  simulate(seconds: number, dt = 1 / 60): void {
    if (!(dt > 0) || !Number.isFinite(dt)) dt = 1 / 60; // a zero step would never advance the loop
    const steps = Math.max(0, Math.round(seconds / dt));
    for (let i = 0; i < steps; i++) this.step(dt);
    this.ctx.renderer.render();
  }

  resize(): void {
    const r = this.ctx.renderer;
    r.resize();
    this.ctx.cameraRig.resize(r.width, r.height);
  }

  snapshot(): Record<string, unknown> {
    const c = this.ctx;
    const p = c.player.position;
    return {
      t: Math.round(c.time.elapsed * 100) / 100,
      phase: c.state.phase,
      // Cash bundles still flying back to the wallet are not banked yet (CashStack.inFlightValue).
      money: c.economy.money + c.player.back.inFlightValue,
      player: { x: Math.round(p.x * 100) / 100, z: Math.round(p.z * 100) / 100 },
      arms: { log: c.player.arms.count('log'), crate: c.player.arms.count('crate'), size: c.player.arms.size },
      cashBundles: c.player.back.count('cash'),
      flights: c.flights.activeCount,
      liveItems: c.items.liveCount,
      unlocked: { ...c.state.unlocked },
      padsVisible: { ...c.state.padsVisible },
      stats: { ...c.state.stats },
      upgrades: { ...c.state.upgrades },
      village: { revealed: c.state.village.revealed, population: c.state.village.population, level: c.state.village.level },
      level: this.level.snapshot(),
    };
  }

  private flushRemovals(): void {
    if (this.pendingRemovals.size === 0) return;
    for (let i = this.updatables.length - 1; i >= 0; i--) {
      if (this.pendingRemovals.has(this.updatables[i]!)) this.updatables.splice(i, 1);
    }
    this.pendingRemovals.clear();
  }

  private installDebugApi(): void {
    const ctx = this.ctx;
    window.__WINTERLAND__ = {
      game: this,
      ctx,
      level: this.level,
      config: { LAYOUT, PADS, ECONOMY, PLAYER, TIMING, UPGRADES, CREW, VILLAGE, DEMAND, QUARTERS, RIDGE, PRESTIGE, BUSINESSES, TOWN },
      state: () => this.snapshot(),
      pause: () => {
        this.paused = true;
      },
      resume: () => {
        this.paused = false;
        this.lastTime = performance.now();
      },
      simulate: (seconds: number, dt?: number) => {
        this.simulate(seconds, dt);
        return this.snapshot();
      },
      render: () => ctx.renderer.render(),
      setMove: (x: number | null, y = 0) => {
        ctx.input.override = x === null ? null : new THREE.Vector2(x, y);
      },
      moveTo: (x: number, z: number) => {
        ctx.player.autopilot = new THREE.Vector3(x, 0, z);
      },
      teleport: (x: number, z: number) => {
        ctx.player.teleport(x, z);
        ctx.cameraRig.snapToTarget();
      },
      addMoney: (n: number) => ctx.economy.add(n),
      skipIntro: () => this.level.skipIntro(),
      unlock: (id: PadId) => this.level.forceUnlock(id),
      buy: (id: UpgradeId) => ctx.upgrades.buy(id),
      setUpgrade: (id: UpgradeId, level: number) => ctx.upgrades.setLevel(id, level),
      revealVillage: () => this.level.village.reveal(),
      buildPlot: (plot: number, tier: number) => this.level.village.debugBuild(plot, tier),
      buildQuarters: (tier: number) => this.level.quarters.debugBuild(tier),
      revealTown: () => this.level.town.reveal(false),
      buildTown: (lot: number, id: BusinessId) => this.level.town.debugBuild(lot, id),
      newSeason: () => ctx.events.emit('season:new', {}),
      startRush: (seconds?: number) => ctx.rush.start(seconds),
      setTimeOfDay: (p: number) => {
        ctx.state.clock = Math.max(0, Math.min(1, p)) * DAYNIGHT.cycleSeconds;
      },
      save: () => this.save(),
      saveData: () => this.saveData(),
      clearSave: () => clearSave(),
      offlinePreview: (seconds: number) =>
        offlineEarnings({ ...this.saveData(), savedAt: Date.now() - seconds * 1000 }, Date.now()),
    };
  }
}
